Lemma tok_suffix_nil : forall W wbs, tok_suffix W (W + Z.of_nat (length wbs)) wbs = [].
Proof. intros W wbs. unfold tok_suffix. replace (W + Z.of_nat (length wbs) - W) with (Z.of_nat (length wbs)) by lia. rewrite Nat2Z.id, skipn_all. reflexivity. Qed.

(* [comment removed for export] *)
Lemma tokit_after_shape : forall r a b, exists x y i f, tokit_cells_after r a b = TokItCells x y i f b /\ (f = a \/ f = b).
Proof.
  intros [| |k l] a b; cbn; [exists 0, 0, b, b| exists 0, 0, b, b| exists (a + Z.of_nat k), (Z.of_nat l), (a + Z.of_nat k + Z.of_nat l), a];
    split; try reflexivity; tauto.
Qed.

